CREATE TABLE IF NOT EXISTS teams(id uuid PRIMARY KEY, name text NOT NULL, rules jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, name text NOT NULL, password text NOT NULL);
CREATE TABLE IF NOT EXISTS members(team_id uuid REFERENCES teams ON DELETE CASCADE, user_id uuid REFERENCES users, role text NOT NULL CHECK(role IN ('owner','admin','member','viewer')), PRIMARY KEY(team_id,user_id));
CREATE TABLE IF NOT EXISTS sessions(token text PRIMARY KEY, user_id uuid REFERENCES users ON DELETE CASCADE, team_id uuid REFERENCES teams ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, checked_at timestamptz);
CREATE TABLE IF NOT EXISTS invites(token text PRIMARY KEY, team_id uuid REFERENCES teams ON DELETE CASCADE, email text NOT NULL, role text NOT NULL CHECK(role IN ('admin','member','viewer')), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS boards(id uuid PRIMARY KEY, team_id uuid REFERENCES teams ON DELETE CASCADE, name text NOT NULL, UNIQUE(team_id,id));
CREATE TABLE IF NOT EXISTS stages(id uuid PRIMARY KEY, team_id uuid NOT NULL, board_id uuid NOT NULL, name text NOT NULL, position integer NOT NULL, FOREIGN KEY(team_id,board_id) REFERENCES boards(team_id,id) ON DELETE CASCADE, UNIQUE(team_id,id));
CREATE TABLE IF NOT EXISTS connectors(key text PRIMARY KEY, label text NOT NULL, kind text NOT NULL, module text);
CREATE TABLE IF NOT EXISTS connections(id uuid PRIMARY KEY, team_id uuid REFERENCES teams ON DELETE CASCADE, owner_id uuid NOT NULL, connector text REFERENCES connectors(key), name text NOT NULL, config jsonb NOT NULL DEFAULT '{}', secret text, enabled boolean NOT NULL DEFAULT true, interval_minutes integer NOT NULL DEFAULT 15 CHECK(interval_minutes BETWEEN 10 AND 30), last_sync timestamptz, last_attempt timestamptz, next_sync timestamptz NOT NULL DEFAULT now(), error text, fetched integer NOT NULL DEFAULT 0, inserted integer NOT NULL DEFAULT 0, FOREIGN KEY(team_id,owner_id) REFERENCES members(team_id,user_id), UNIQUE(team_id,id));
CREATE TABLE IF NOT EXISTS listings(id uuid PRIMARY KEY, team_id uuid REFERENCES teams ON DELETE CASCADE, platform text NOT NULL, external_id text NOT NULL, url text, title text NOT NULL, description text, budget numeric, currency text, payment_type text, skills jsonb NOT NULL DEFAULT '[]', client jsonb, geography text, responses integer, published_at timestamptz, source_updated_at timestamptz, source_status text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), stage_id uuid, assignee_id uuid, priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')), archived boolean NOT NULL DEFAULT false, score integer NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100), breakdown jsonb NOT NULL DEFAULT '[]', excluded boolean NOT NULL DEFAULT false, UNIQUE(team_id,platform,external_id), UNIQUE(team_id,id), FOREIGN KEY(team_id,stage_id) REFERENCES stages(team_id,id), FOREIGN KEY(team_id,assignee_id) REFERENCES members(team_id,user_id));
CREATE TABLE IF NOT EXISTS listing_sources(team_id uuid NOT NULL, listing_id uuid NOT NULL, connection_id uuid NOT NULL, PRIMARY KEY(listing_id,connection_id), FOREIGN KEY(team_id,listing_id) REFERENCES listings(team_id,id) ON DELETE CASCADE, FOREIGN KEY(team_id,connection_id) REFERENCES connections(team_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS favorites(team_id uuid NOT NULL, listing_id uuid NOT NULL, user_id uuid NOT NULL, PRIMARY KEY(listing_id,user_id), FOREIGN KEY(team_id,listing_id) REFERENCES listings(team_id,id) ON DELETE CASCADE, FOREIGN KEY(team_id,user_id) REFERENCES members(team_id,user_id));
CREATE TABLE IF NOT EXISTS notes(id uuid PRIMARY KEY, team_id uuid NOT NULL, listing_id uuid NOT NULL, user_id uuid REFERENCES users, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(team_id,listing_id) REFERENCES listings(team_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS history(id bigserial PRIMARY KEY, team_id uuid REFERENCES teams, listing_id uuid, user_id uuid REFERENCES users, action text NOT NULL, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(team_id,listing_id) REFERENCES listings(team_id,id));
CREATE TABLE IF NOT EXISTS duplicates(team_id uuid NOT NULL, left_id uuid NOT NULL, right_id uuid NOT NULL, similarity numeric NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','confirmed','dismissed')), PRIMARY KEY(left_id,right_id), FOREIGN KEY(team_id,left_id) REFERENCES listings(team_id,id), FOREIGN KEY(team_id,right_id) REFERENCES listings(team_id,id));
CREATE TABLE IF NOT EXISTS jobs(id bigserial PRIMARY KEY, team_id uuid NOT NULL, connection_id uuid NOT NULL, status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','done','failed')), run_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, error text, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(team_id,connection_id) REFERENCES connections(team_id,id) ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS jobs_one_active ON jobs(connection_id) WHERE status IN ('queued','running');
CREATE INDEX IF NOT EXISTS jobs_ready ON jobs(status,run_at);
CREATE INDEX IF NOT EXISTS listing_feed ON listings(team_id,archived,published_at DESC);
CREATE INDEX IF NOT EXISTS listing_stage ON listings(team_id,stage_id);
CREATE TABLE IF NOT EXISTS login_attempts(key text PRIMARY KEY, count integer NOT NULL, reset_at timestamptz NOT NULL);
INSERT INTO connectors(key,label,kind) VALUES('mock','Mock Studio','mock'),('rss','RSS / Atom','rss'),('json','Разрешённый JSON API','api') ON CONFLICT DO NOTHING;
